"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["9429"],{44245(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.precedencia_fase.self_loop","status":422,"titulo":"A fase antecessora n\xe3o pode ser igual \xe0 fase sucessora"},"descricao":{"codigo":"uniplus.configuracao.precedencia_fase.self_loop","requisitos":[],"oQueAconteceu":["O cadastro de uma preced\xeancia (`POST /api/configuracao/admin/precedencias-fase`) trouxe o mesmo c\xf3digo de fase em `antecessoraCodigo` e em `sucessoraCodigo`. Uma fase n\xe3o pode vir antes de si mesma, e uma preced\xeancia assim tornaria imposs\xedvel de cumprir qualquer cronograma que contivesse a fase.","Esta confer\xeancia s\xf3 roda quando os dois c\xf3digos s\xe3o v\xe1lidos, isto \xe9, bem formados e do vocabul\xe1rio de fases; com problema em um deles, a resposta \xe9 a recusa do c\xf3digo (por exemplo, `uniplus.configuracao.precedencia_fase.antecessora_fora_do_conjunto_canonico`). A resposta traz o c\xf3digo de erro e a mensagem, sem a lista `errors`. Nada \xe9 gravado."],"comoResolver":["Informe duas fases diferentes: a que vem antes e a que vem depois. Os c\xf3digos v\xe1lidos v\xeam de `GET /api/configuracao/vocabularios/fases-canonicas`."],"ondeAparece":["Cadastro de uma preced\xeancia entre fases"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Precedencia fase"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);